// generated by tools/gen_esp.py from the lore book and the guide - do not edit
#pragma once
#include <array>
#include <string_view>
#include <vector>
namespace bo3z::codex
{
	struct Chapter { int book; std::string_view title, image; std::vector<std::string_view> paras; };
	inline constexpr std::array<std::string_view, 5> kBooks{ "The Curse of Alduin", "The Summoner's Path", "The Battle-mage's Path", "The Ranger's Path", "The Spellsword's Path" };  // 0 the lore, 1-4 the class guides (Summoner, Destruction, Ranger, Spellsword)
	inline const std::vector<Chapter> kChapters{
		{ 0, "The Greybeard's Account", "sigil", { "Written at High Hrothgar by a Greybeard who broke his silence, for whoever lived through Helgen" } },
		{ 0, "I. What Happened", "helgen", { "When Alduin rose over Helgen, he shouted three Words into the earth: <b>SLEN TIID VO</b> - Flesh, Time, Undo. It is the shout that raises the dead.", "His mist also covers the door of <b>Sovngarde</b>, so the dead of Skyrim cannot pass on. They lie restless in the ground. By day they sleep. When the sun goes down, they rise." } },
		{ 0, "II. The Dead", "graves", { "Each night the dead come in <b>waves</b>, more of them and harder to kill as the nights go on. They claw up out of open ground - roads and fields, never inside a house - and come at you from every side. Dawn comes only when the last wave falls.", "Four kinds make up the horde:", "<b>Risen Dead</b> - the most common. Wound one past half and it turns frenzied. Finish them fast.", "<b>Draugr Brides</b> - quick and frail. They leap at you from a distance.", "<b>Drowned Skalds</b> - their scream raises more dead and drives the horde faster. Kill them first.", "<b>Volatiles</b> - bladed brutes. Their hide turns half of every blow unless you strike the head or the back.", "Noise draws worse. Loud spells, shouts and running wake an elite Volatile, faster still, that comes through a portal and pounces. The Curse's champions and great ones step out of portals too - and their names burn gold over their heads." } },
		{ 0, "III. The Echo Altars", "wards", { "Long ago the <b>Tongues</b>, the first masters of the Voice, raised an altar in every hold to hold Alduin's shout back. Every mage who fell in the Dragon War gave a last spell to them, which is why an altar still has spells, bows and gifts to give.", "Alduin's return woke the altars only halfway. Each one is held silent by a <b>Dragon Priest</b>, still bound by his old oath to Alduin." } },
		{ 0, "IV. Waking an Altar", "", { "Stand at an altar and it sets you <b>trials</b>: hold its rune circle, cull the dead in its streets, hold the altar through a night's waves, and pass the trial of your own path. Finish them and its Dragon Priest rises at night. Kill him and the altar wakes.", "A woken altar makes its city a <b>sanctuary</b> - no dead rise inside it. If you have walked the <b>Way of the Voice</b> at High Hrothgar, its heart-stone also teaches you the city's own <b>shout</b>." } },
		{ 0, "V. The Dragonborn's Road", "", { "The Curse walks beside your own story; it does not replace it.", "<b>Riverwood's</b> altar, nearest Helgen, wakes first. <b>Whiterun's</b> answers your first dragon soul and gives you a dragon to ride. At <b>High Hrothgar</b>, the Way of the Voice opens the altars' shouts, and the <b>Reliquary</b> forges what the Dragon Priests leave behind into wonders.", "When you follow Alduin to Sovngarde and he falls, the mist thins and your wonders wake to their <b>Legendary</b> form. His three Words still lie in the ground: silence <b>SLEN</b>, <b>TIID</b> and <b>VO</b> at the old places of the Dragon Cult, and the Curse is broken for good." } },
		{ 0, "VI. The Voices of the Holds", "", { "<b>Riverwood</b>: <i>Thunder Lash</i> (STRUN BAH QO). Lightning strikes the nearest dead - three, five or eight bolts, each leaping to one more.", "<b>Solitude</b>: <i>Raise the Fallen</i> (DIL VAAZ ZOL). The fallen rise to fight for you - two, four or six of them - and burst when their time is up.", "<b>Windhelm</b>: <i>Frost Nova</i> (IIZ SLEN NUS). A ring of frost freezes everything around you solid, and the frozen shatter when struck.", "<b>Markarth</b>: <i>Dwemer Quake</i> (GOL VAH DEN). The ground heaves in front of you and knocks the dead down - with the third word, stone spikes erupt through them.", "<b>Riften</b>: <i>Shadow Step</i> (FEIM ZII GRON). You blink forward through the horde, leaving a shadow that draws the dead to it and then bursts.", "<b>Falkreath</b>: <i>Death's Harvest</i> (KRII LUN AUS). A draining cone that heals you for every one of the dead it touches - the third word also raises a fallen friend nearby.", "<b>Morthal</b>: <i>Mire Grasp</i> (ZUN HAAL VIIK). Roots burst from the ground where you look, holding the dead in place and poisoning them.", "<b>Dawnstar</b>: <i>Nightmare Howl</i> (FAAS RU MAAR). The dead are thrown back in terror and slowed - and the weakest die of fright.", "<b>Winterhold</b>: <i>Arcane Singularity</i> (SU GRAH DUN). A vortex pulls the dead together where you look, then detonates.", "<b>Whiterun</b>: <i>Dragon's Updraft</i>. A whirlwind lifts you high - and a dragon to carry you." } },
		{ 0, "Epilogue", "", { "Every Echo Altar in Skyrim is awake. Alduin's voice lingers only in the wild places, and the mist will not lift from Sovngarde's door until the World-Eater falls.", "<i>- written in the silence of High Hrothgar</i>" } },
		{ 1, "The Summoner", "", { "A conjurer of the <b>College of Winterhold</b>. Your summons fight for you - every kill they make is yours: essence, progress and trials.", "<b>You start with</b> Conjure Skeleton (right hand), Conjure Wolf (left hand) and the summoner's robes." } },
		{ 1, "Your Progress", "@progress", {  } },
		{ 1, "Your Altar", "", { "<b>Call a Summon</b> - the first rung of a summon family you don't have. You carry two families at a time.", "<b>Bind a Hero</b> - your Legendary pact: a hero of old (Ysgramor, Miraak, the Ebony Warrior...) or a great army. Opens at <b>six freed altars</b>.", "The five families: <b>the Dead</b> (Skeleton to Death Overlord), <b>Beasts</b> (Wolf to Werebear), <b>Daedra</b> (Dremora to Warlock), <b>Dwemer</b> (Spider to Ballista Master) and <b>the Wild</b> (Spriggan to Earth Mother)." } },
		{ 1, "Getting Stronger", "", { "<b>Kills fill it, the altar raises it.</b> Kills with the spell in your hand count toward its next rung - <b>25</b>, then <b>60</b>, then <b>120</b> for the Legendary rung - once three Echo Altars are freed. Then hold it and take the altar's <b>Reforge</b> row: <b>5,000</b>, <b>8,000</b>, then <b>12,000</b> essence, once a night per spell. The altar's Reforge row and <i>Your Progress</i> show the count.", "<b>Command</b> - how many summons you can have out at once. You start with 1; it grows to 2, 3 and 4 as your two carried families climb (1, 3 and 6 climbs in all). At the limit a new summon replaces the oldest." } },
		{ 1, "Your Perks", "", { "<b>Bonebinder's Brew</b> - summons have 50% more health and hit 50% harder.", "<b>Soul-Tether Wine</b> - each summon kill heals you 5%.", "<b>Conjurer's Command Mead</b> - one more summon at once (up to 5).", "One of each perk a life - death takes them all." } },
		{ 1, "Your Trial and Wonder", "", { "<b>Pact of the Host</b> (your city trial): let your summons make the kills - 10 on Novice up to 30 on Legendary.", "<b>Horn of the Spectral Wyrm</b> (your wonder): after three freed cities, 40 summon kills in each of three cities. It calls a spectral dragon for a minute - until it falls once Alduin is slain." } },
		{ 1, "How a Night Works", "", { "<b>Day</b> (about 20 minutes): the dead sleep. Explore, rest and spend your essence.", "<b>Night</b>: the dead claw up out of the ground (on open ground, never in houses) in <b>waves</b> - fast runners, more and tougher each night, coming from every side. Elites and bosses step out of the Curse's portals. Dawn only comes when the last wave falls.", "The night's dead come in four kinds: the <b>Risen Dead</b> run you down and, hurt past half, shriek and turn frenzied - finish them fast; the <b>Draugr Bride</b> is quick and frail and leaps on you from a distance; the <b>Drowned Skald</b> screams up more dead and drives the horde faster - kill it first; the <b>Volatile</b>, a bladed brute, shrugs off half of every blow unless you hit its head or its back.", "<b>Noise</b> brings worse: spells bursting, shouts and sprinting fill the <i>Noise</i> bar under the wave count; let it fill and an elite <b>Volatile</b> comes through a portal for you - far faster, and it pounces. Go quiet and it drains.", "<b>Essence</b> drops from every kill - spend it at the Echo Altars. Watch for tokens: skull (Insta-Kill), coin (Double Points), falling star (destroys tonight's corpses), chest (Fire Sale).", "Your health, magicka and stamina sit on one plate at the bottom; its rim glows blue while your shout recovers." } },
		{ 1, "The Echo Altar", "", { "Every city has one. Step onto it and activate it. Move with the D-pad or W/S, choose with A or Enter, leave with B.", "From the top: <b>your class</b> (change it for 2,500 essence - each class keeps its own progress), <b>your rolls</b>, <b>Reforge</b> (after three freed altars), <b>perks</b>, then the city's <b>trials</b>.", "<b>After a roll</b>, activate the altar again: <b>take it</b> (it replaces what it would), <b>roll again</b> at the next price, or <b>leave it</b> for half the roll back.", "<b>Freeing a city</b>: finish four trials (three shared, one your class's), then slay its <b>Dragon Priest</b>, who rises at night. A freed city is a sanctuary, teaches you its Thu'um, and Whiterun gives you a dragon to ride." } },
		{ 1, "Settings", "", { "<b>Difficulty</b> is Skyrim's own (Settings, Gameplay). From Novice to Legendary the dead have <b>0.6x, 0.8x, 1x, 1.6x, 2.2x, 3x</b> health and hit <b>0.5x to 2x</b> as hard. Until three altars are freed, on Adept or harder, no single hit takes more than 60% of a zombie's health.", "Skyrim's own enemies get tougher with the difficulty and with every altar you free, so they keep up with you.", "The <b>Mod Configuration Menu</b> page <i>The Curse of Alduin</i> has the rest: attack and draw speed, field of view, brightness, effects and controls." } },
		{ 2, "The Battle-mage", "", { "A battle-mage of the <b>College of Winterhold</b>: a different element in each hand.", "<b>You start with</b> Scorch (right hand), Hoarfrost (left hand), the Wild Witch's hat and gown and a Destruction tome." } },
		{ 2, "Your Progress", "@progress", {  } },
		{ 2, "Your Altar", "", { "<b>Call a Spell</b> - the first rung of an element you don't have. You carry two at a time.", "<b>Call a Support Spell</b> - Ash Cloud, Cinder Storm, Charged Nova or Symmetry, yours to keep.", "The six elements: <b>Fire</b>, <b>Frost</b>, <b>Shock</b>, <b>Sun</b>, <b>Poison</b> and <b>Blood</b>, four rungs each." } },
		{ 2, "Getting Stronger", "", { "<b>Kills fill it, the altar raises it.</b> Kills with the spell in your hand count toward its next rung - <b>25</b>, then <b>60</b>, then <b>120</b> for the Legendary rung - once three Echo Altars are freed. Then hold it and take the altar's <b>Reforge</b> row: <b>5,000</b>, <b>8,000</b>, then <b>12,000</b> essence, once a night per spell. The altar's Reforge row and <i>Your Progress</i> show the count." } },
		{ 2, "Your Perks", "", { "<b>Ember Heart Ale</b> - Destruction kills burst and hurt the dead nearby.", "<b>Arcanist's Focus Tea</b> - Destruction spells cost 25% less magicka.", "<b>Mana-Siphon Draught</b> - each Destruction kill gives back 6% magicka.", "One of each perk a life - death takes them all." } },
		{ 2, "Your Trial and Wonder", "", { "<b>Trial of the Elements</b> (your city trial): kill with two or more elements - 10 on Novice up to 30 on Legendary.", "<b>Tome of the Six Fires</b> (your wonder): after three freed cities, 40 Destruction kills in each of three cities. One cast looses the top spell of all six elements around you." } },
		{ 2, "How a Night Works", "", { "<b>Day</b> (about 20 minutes): the dead sleep. Explore, rest and spend your essence.", "<b>Night</b>: the dead claw up out of the ground (on open ground, never in houses) in <b>waves</b> - fast runners, more and tougher each night, coming from every side. Elites and bosses step out of the Curse's portals. Dawn only comes when the last wave falls.", "The night's dead come in four kinds: the <b>Risen Dead</b> run you down and, hurt past half, shriek and turn frenzied - finish them fast; the <b>Draugr Bride</b> is quick and frail and leaps on you from a distance; the <b>Drowned Skald</b> screams up more dead and drives the horde faster - kill it first; the <b>Volatile</b>, a bladed brute, shrugs off half of every blow unless you hit its head or its back.", "<b>Noise</b> brings worse: spells bursting, shouts and sprinting fill the <i>Noise</i> bar under the wave count; let it fill and an elite <b>Volatile</b> comes through a portal for you - far faster, and it pounces. Go quiet and it drains.", "<b>Essence</b> drops from every kill - spend it at the Echo Altars. Watch for tokens: skull (Insta-Kill), coin (Double Points), falling star (destroys tonight's corpses), chest (Fire Sale).", "Your health, magicka and stamina sit on one plate at the bottom; its rim glows blue while your shout recovers." } },
		{ 2, "The Echo Altar", "", { "Every city has one. Step onto it and activate it. Move with the D-pad or W/S, choose with A or Enter, leave with B.", "From the top: <b>your class</b> (change it for 2,500 essence - each class keeps its own progress), <b>your rolls</b>, <b>Reforge</b> (after three freed altars), <b>perks</b>, then the city's <b>trials</b>.", "<b>After a roll</b>, activate the altar again: <b>take it</b> (it replaces what it would), <b>roll again</b> at the next price, or <b>leave it</b> for half the roll back.", "<b>Freeing a city</b>: finish four trials (three shared, one your class's), then slay its <b>Dragon Priest</b>, who rises at night. A freed city is a sanctuary, teaches you its Thu'um, and Whiterun gives you a dragon to ride." } },
		{ 2, "Settings", "", { "<b>Difficulty</b> is Skyrim's own (Settings, Gameplay). From Novice to Legendary the dead have <b>0.6x, 0.8x, 1x, 1.6x, 2.2x, 3x</b> health and hit <b>0.5x to 2x</b> as hard. Until three altars are freed, on Adept or harder, no single hit takes more than 60% of a zombie's health.", "Skyrim's own enemies get tougher with the difficulty and with every altar you free, so they keep up with you.", "The <b>Mod Configuration Menu</b> page <i>The Curse of Alduin</i> has the rest: attack and draw speed, field of view, brightness, effects and controls." } },
		{ 3, "The Ranger", "", { "Sworn to the <b>Dawnguard</b>. Bows and crossbows - every arrow counts.", "<b>You start with</b> an elemental bow, the Dawnguard Crossbow with 30 bolts and the Drifter Outfit." } },
		{ 3, "Your Progress", "@progress", {  } },
		{ 3, "Your Altar", "", { "<b>Call a Bow or Crossbow</b> - one roll: six times in ten an elemental bow, four times in ten a crossbow or offhand bow. You carry one elemental bow; a new one takes its place.", "The bows: <b>Emberstring</b> (fire), <b>Rimehorn</b> (frost), <b>Stormreach</b> (shock), <b>Skyhowl</b> (wind), <b>Dawnspire</b> (sun), <b>Thirstbow</b> (blood). A full draw hits hardest.", "Better crossbows come as cities are freed (Dwarven and Elven at one, Glass and Ebony at two, Daedric and Dragonbone at three). <b>Q</b> / <b>R3</b> at the altar fills your quivers." } },
		{ 3, "Getting Stronger", "", { "<b>Kills fill it, the altar raises it.</b> Kills with a bow count toward its next tier - <b>25</b>, <b>60</b>, then <b>120</b> - once three Echo Altars are freed. Then hold it and take the altar's <b>Reforge</b> row: <b>5,000</b>, <b>8,000</b>, <b>12,000</b> essence, once a night.", "Each tier: more damage, a new attack and a bigger quiver - <b>60</b>, <b>100</b>, <b>150</b>, <b>200</b> arrows - that regrows one arrow every <b>8</b>, <b>6</b>, <b>4</b>, then <b>2</b> seconds.", "<b>Crossbows</b>: kills unlock elemental bolts - fire at 25, ice at 60, shock at 120." } },
		{ 3, "Your Perks", "", { "<b>Fletcher's Sap Draught</b> - your arrows or bolts slowly grow back.", "<b>Eagle-Eye Draught</b> - bows draw and crossbows reload 25% faster.", "<b>Dawnwatch Tonic</b> - with a bow or crossbow out, the dead hurt you 25% less.", "One of each perk a life - death takes them all." } },
		{ 3, "Your Trial and Wonder", "", { "<b>Trial of the Long Shot</b> (your city trial): bow or crossbow kills from 30 m or more - 10 on Novice up to 30 on Legendary.", "<b>The Subsuming Vortex</b> (your wonder): after three freed cities, 40 bow or crossbow kills in each of three cities. Its arrows open black holes that drag the dead in, then burst - wider and stronger once Alduin is slain." } },
		{ 3, "How a Night Works", "", { "<b>Day</b> (about 20 minutes): the dead sleep. Explore, rest and spend your essence.", "<b>Night</b>: the dead claw up out of the ground (on open ground, never in houses) in <b>waves</b> - fast runners, more and tougher each night, coming from every side. Elites and bosses step out of the Curse's portals. Dawn only comes when the last wave falls.", "The night's dead come in four kinds: the <b>Risen Dead</b> run you down and, hurt past half, shriek and turn frenzied - finish them fast; the <b>Draugr Bride</b> is quick and frail and leaps on you from a distance; the <b>Drowned Skald</b> screams up more dead and drives the horde faster - kill it first; the <b>Volatile</b>, a bladed brute, shrugs off half of every blow unless you hit its head or its back.", "<b>Noise</b> brings worse: spells bursting, shouts and sprinting fill the <i>Noise</i> bar under the wave count; let it fill and an elite <b>Volatile</b> comes through a portal for you - far faster, and it pounces. Go quiet and it drains.", "<b>Essence</b> drops from every kill - spend it at the Echo Altars. Watch for tokens: skull (Insta-Kill), coin (Double Points), falling star (destroys tonight's corpses), chest (Fire Sale).", "Your health, magicka and stamina sit on one plate at the bottom; its rim glows blue while your shout recovers." } },
		{ 3, "The Echo Altar", "", { "Every city has one. Step onto it and activate it. Move with the D-pad or W/S, choose with A or Enter, leave with B.", "From the top: <b>your class</b> (change it for 2,500 essence - each class keeps its own progress), <b>your rolls</b>, <b>Reforge</b> (after three freed altars), <b>perks</b>, then the city's <b>trials</b>.", "<b>After a roll</b>, activate the altar again: <b>take it</b> (it replaces what it would), <b>roll again</b> at the next price, or <b>leave it</b> for half the roll back.", "<b>Freeing a city</b>: finish four trials (three shared, one your class's), then slay its <b>Dragon Priest</b>, who rises at night. A freed city is a sanctuary, teaches you its Thu'um, and Whiterun gives you a dragon to ride." } },
		{ 3, "Settings", "", { "<b>Difficulty</b> is Skyrim's own (Settings, Gameplay). From Novice to Legendary the dead have <b>0.6x, 0.8x, 1x, 1.6x, 2.2x, 3x</b> health and hit <b>0.5x to 2x</b> as hard. Until three altars are freed, on Adept or harder, no single hit takes more than 60% of a zombie's health.", "Skyrim's own enemies get tougher with the difficulty and with every altar you free, so they keep up with you.", "The <b>Mod Configuration Menu</b> page <i>The Curse of Alduin</i> has the rest: attack and draw speed, field of view, brightness, effects and controls." } },
		{ 4, "The Spellsword", "", { "A <b>Vigilant of Stendarr</b>: steel in one hand, a touch spell in the other.", "<b>You start with</b> the Steel Spellsword, a Steel Spellshield, Flame Touch (left hand) and the Practical Pirate outfit." } },
		{ 4, "Your Progress", "@progress", {  } },
		{ 4, "Your Altar", "", { "<b>Call a Spell</b> - the first rung of a touch spell you don't have: Fire, Frost, Shock, Sun, Blood or Poison (three rungs each). You carry two at a time.", "<b>Call a Spell-Weapon</b> - a spellsword, greatsword or spellshield (sometimes a Mysticism shell or cloak). Better steel comes as cities are freed." } },
		{ 4, "Getting Stronger", "", { "<b>Kills fill it, the altar raises it.</b> Melee kills with the spell in your other hand count toward its next rung - <b>25</b>, then <b>60</b> (a power-attack kill counts twice) - once three Echo Altars are freed. Then take the altar's <b>Reforge</b> row: <b>5,000</b> then <b>8,000</b> essence, once a night.", "Each reforge also raises your held spell-weapon a material and unlocks one of four <b>Enchantment Powers</b> (in your Powers)." } },
		{ 4, "Your Perks", "", { "<b>Bladesong Mead</b> - each melee hit heals you 2%.", "<b>Spellbinder's Draught</b> - melee kills give back 10% magicka.", "<b>Steel-Wind Ale</b> - melee swings 20% faster.", "One of each perk a life - death takes them all." } },
		{ 4, "Your Trial and Wonder", "", { "<b>Trial of Steel</b> (your city trial): melee kills with a spell in your other hand - 10 on Novice up to 30 on Legendary.", "<b>Dragon Slayer</b> (your wonder): after three freed cities, 40 melee kills in each of three cities. Every hit carries your off-hand spell; once Alduin is slain, power attacks send it down the line." } },
		{ 4, "How a Night Works", "", { "<b>Day</b> (about 20 minutes): the dead sleep. Explore, rest and spend your essence.", "<b>Night</b>: the dead claw up out of the ground (on open ground, never in houses) in <b>waves</b> - fast runners, more and tougher each night, coming from every side. Elites and bosses step out of the Curse's portals. Dawn only comes when the last wave falls.", "The night's dead come in four kinds: the <b>Risen Dead</b> run you down and, hurt past half, shriek and turn frenzied - finish them fast; the <b>Draugr Bride</b> is quick and frail and leaps on you from a distance; the <b>Drowned Skald</b> screams up more dead and drives the horde faster - kill it first; the <b>Volatile</b>, a bladed brute, shrugs off half of every blow unless you hit its head or its back.", "<b>Noise</b> brings worse: spells bursting, shouts and sprinting fill the <i>Noise</i> bar under the wave count; let it fill and an elite <b>Volatile</b> comes through a portal for you - far faster, and it pounces. Go quiet and it drains.", "<b>Essence</b> drops from every kill - spend it at the Echo Altars. Watch for tokens: skull (Insta-Kill), coin (Double Points), falling star (destroys tonight's corpses), chest (Fire Sale).", "Your health, magicka and stamina sit on one plate at the bottom; its rim glows blue while your shout recovers." } },
		{ 4, "The Echo Altar", "", { "Every city has one. Step onto it and activate it. Move with the D-pad or W/S, choose with A or Enter, leave with B.", "From the top: <b>your class</b> (change it for 2,500 essence - each class keeps its own progress), <b>your rolls</b>, <b>Reforge</b> (after three freed altars), <b>perks</b>, then the city's <b>trials</b>.", "<b>After a roll</b>, activate the altar again: <b>take it</b> (it replaces what it would), <b>roll again</b> at the next price, or <b>leave it</b> for half the roll back.", "<b>Freeing a city</b>: finish four trials (three shared, one your class's), then slay its <b>Dragon Priest</b>, who rises at night. A freed city is a sanctuary, teaches you its Thu'um, and Whiterun gives you a dragon to ride." } },
		{ 4, "Settings", "", { "<b>Difficulty</b> is Skyrim's own (Settings, Gameplay). From Novice to Legendary the dead have <b>0.6x, 0.8x, 1x, 1.6x, 2.2x, 3x</b> health and hit <b>0.5x to 2x</b> as hard. Until three altars are freed, on Adept or harder, no single hit takes more than 60% of a zombie's health.", "Skyrim's own enemies get tougher with the difficulty and with every altar you free, so they keep up with you.", "The <b>Mod Configuration Menu</b> page <i>The Curse of Alduin</i> has the rest: attack and draw speed, field of view, brightness, effects and controls." } },
	};
}
